import { randomUUID,createCipheriv,randomBytes } from 'node:crypto';import { z } from 'zod';import { getDb } from '../../../../lib/db';import { getSession } from '../../../../lib/session';import { jsonError,jsonOk,readJson } from '../../../../lib/http';
const schema=z.object({amount:z.number().positive().max(100000000),bankName:z.string().trim().min(2).max(120),accountName:z.string().trim().min(2).max(160),accountNumber:z.string().regex(/^\d{10}$/,'Enter a valid 10 digit account number.')});
function encryptAccount(value){const secret=process.env.SESSION_SECRET;if(!secret||secret.length<32)throw new Error('SESSION_SECRET is not configured.');const key=Buffer.from(secret).subarray(0,32);const iv=randomBytes(12);const cipher=createCipheriv('aes-256-gcm',key,iv);const encrypted=Buffer.concat([cipher.update(value,'utf8'),cipher.final()]);return Buffer.concat([iv,cipher.getAuthTag(),encrypted]).toString('base64');}
export async function GET(){const user=await getSession();if(!user)return jsonError('Please sign in.',401);if(user.role!=='VENDOR')return jsonError('Vendor access required.',403);try{const db=getDb();const [rows]=await db.execute('SELECT w.id,w.amount,w.bank_name,w.account_name,w.status,w.admin_note,w.created_at FROM withdrawals w JOIN vendors v ON v.id=w.vendor_id WHERE v.user_id=? ORDER BY w.created_at DESC LIMIT 100',[user.id]);return jsonOk({withdrawals:rows});}catch(e){console.error('Withdrawal list error:',e);return jsonError('Could not load withdrawal requests.',500);}}
export async function POST(request){const user=await getSession();if(!user)return jsonError('Please sign in.',401);if(user.role!=='VENDOR')return jsonError('Vendor access required.',403);const parsed=schema.safeParse(await readJson(request));if(!parsed.success)return jsonError(parsed.error.issues[0]?.message||'Check withdrawal details.');try{const db=getDb(),conn=await db.getConnection();const id=randomUUID();try{await conn.beginTransaction();const [vs]=await conn.execute('SELECT id,approved FROM vendors WHERE user_id=? LIMIT 1 FOR UPDATE',[user.id]);const vendor=vs[0];if(!vendor||!vendor.approved){await conn.rollback();return jsonError('Your vendor account must be approved to withdraw.',403);}const [ws]=await conn.execute('SELECT id,available_balance FROM wallets WHERE vendor_id=? FOR UPDATE',[vendor.id]);const wallet=ws[0];if(!wallet||Number(wallet.available_balance)<parsed.data.amount){await conn.rollback();return jsonError('Your available wallet balance is insufficient.',400);}const encrypted=encryptAccount(parsed.data.accountNumber);await conn.execute('UPDATE wallets SET available_balance=available_balance-? WHERE id=?',[parsed.data.amount,wallet.id]);await conn.execute('INSERT INTO wallet_entries (id,wallet_id,entry_type,amount,description,reference) VALUES (?,?,\'WITHDRAWAL\',?,?,?)',[randomUUID(),wallet.id,-parsed.data.amount,'Withdrawal requested',`WD-${id}`]);await conn.execute('INSERT INTO withdrawals (id,vendor_id,amount,bank_name,account_name,account_number_enc,status) VALUES (?,?,?,?,?,?,\'PENDING\')',[id,vendor.id,parsed.data.amount,parsed.data.bankName,parsed.data.accountName,encrypted]);await conn.commit();}catch(e){await conn.rollback();throw e;}finally{conn.release();}return jsonOk({ok:true,id,status:'PENDING'},201);}catch(e){console.error('Withdrawal create error:',e);return jsonError('Could not submit withdrawal. Please try again.',500);}}
